mapper.select:
SELECT
A2.BOOKSET_ID bookSetId,

(case
when A.BASE_SUBJECT_NATURE = 'QTYSK_BJ'
then  '其他应收款-本金'
when A.BASE_SUBJECT_NATURE = 'QTYSK_LX'
then  '其他应收款-本金'
end) AS receivablesType,
A2.FINPROD_ID AS bdFinprodId,
B.FINPROD_NAME   AS bdFinprodName ,
A2.prinamt,
A2.intamt,
CASE WHEN A2.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN DATE_FORMAT(D.VDATE,'%Y-%m-%d') ELSE NULL END vdate,
CASE WHEN A2.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN DATE_FORMAT(D.MDATE,'%Y-%m-%d') ELSE NULL END mdate,
CASE WHEN A2.BASE_SUBJECT_NATURE = 'QTYSK_BJ' THEN DATE_FORMAT(D.MDATE,'%Y-%m-%d') ELSE NULL END tradeDate,
CALC.BASIS basis,
CALC.CALC_TYPE calcType,
CALC.YIELD yield
FROM (
SELECT
A1.BOOKSET_ID,
A1.BUSI_ID AS FINPROD_ID,
B.BUSI_DETAIL_TYPE AS FINPROD_TYPE,
A1.BRANCH,
A1.BASE_SUBJECT_NATURE,
SUM(CASE WHEN A1.BASE_SUBJECT_NATURE ='QTYSK_BJ' THEN A1.O_AMT_HAPPEN_DATE ELSE 0 END) AS PRINAMT,
SUM(CASE WHEN A1.BASE_SUBJECT_NATURE ='QTYSK_LX' THEN A1.O_AMT_HAPPEN_DATE ELSE 0 END) AS INTAMT
FROM (
SELECT A.* FROM (
SELECT
bc.BOOKSET_ID,
bc.BUSI_ID,
bc.BRANCH,
bc.BOOK_DATE,
bc.BOK_DETAIL_ID,
bc.BASE_SUBJECT_NATURE,
bc.O_AMT_HAPPEN_DATE,
newResult
from (
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID and
@BOK_DETAIL_ID = tmp.BOK_DETAIL_ID and
@BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE and
@BRANCH = tmp.BRANCH and
@SUBJECT_NO = tmp.SUBJECT_NO
),
@rank := @rank + 1,
@rank := 1
) AS newResult, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件2 */
, @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件3 */
, @BRANCH := tmp.BRANCH /* 分组条件4 */
, @SUBJECT_NO := tmp.SUBJECT_NO /* 分组条件5 */
FROM  (
/* 数据源 */
SELECT bc.*
FROM BOK_BOOKDETAIL_CURRENT bc
ORDER BY CAST(bc.BOOK_ORDER as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@BOK_DETAIL_ID = null,
@BASE_SUBJECT_NATURE = null,
@BRANCH = null,
@SUBJECT_NO = null,
@rank := 0) a
) result ) bc



WHERE bc.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX')
AND bc.BOOK_DATE <= STR_TO_DATE(#{bookDate},'%Y-%m-%d')

	AND bc.BASE_SUBJECT_NATURE = #{receivablesType}


	AND bc.BOOKSET_ID = #{bookSetId}


	AND bc.BUSI_ID in

		#{bdFinprodId}


) A WHERE A.newResult=1
AND A.O_AMT_HAPPEN_DATE != 0
)  A1,BOK_DETAIL_ID B
WHERE A.BOOKSET_ID = B.BOOKSET_ID
AND A.BOK_DETAIL_ID = B.BOK_DETAIL_ID

	AND A.BASE_SUBJECT_NATURE = #{receivablesType}


	AND A.BOOKSET_ID = #{bookSetId}


	AND A.BUSI_ID in

		#{bdFinprodId}


GROUP BY A.BOOKSET_ID, A.BUSI_ID,B.BUSI_DETAIL_TYPE,A.BRANCH, A.BASE_SUBJECT_NATURE
) A2
LEFT JOIN (
SELECT
R.FINPROD_ID,R.FINPROD_TYPE,
(case
when R.CALC_TYPE = '01'
then '固定利率'
when R.CALC_TYPE = '02'
then '浮动利率'
end) AS CALC_TYPE,
ROUND(R.YIELD*100,4) YIELD,R.BASIS FROM FIN_CASH_CALC_RULE R,(
SELECT G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE,MAX(F.EFF_DATE) EFF_DATE
FROM FIN_CASH_CALC_RULE F,FIN_CASH_INFO G
WHERE F.FINPROD_ID = G.FINPROD_ID AND F.FINPROD_TYPE = G.FINPROD_TYPE
AND G.CASH_TYPE_1 ='02'
GROUP BY G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE
) H
WHERE R.CASH_ID = H.CASH_ID AND R.FINPROD_ID = H.FINPROD_ID
AND R.FINPROD_TYPE = H.FINPROD_TYPE
AND R.EFF_DATE = H.EFF_DATE
) CALC ON A2.FINPROD_ID = CALC.FINPROD_ID AND A2.FINPROD_TYPE = CALC.FINPROD_TYPE
LEFT JOIN FIN_PRODUCT B ON A2.FINPROD_ID = B.FINPROD_ID AND A2.FINPROD_TYPE = B.FINPROD_TYPE
LEFT JOIN FIN_TRADE_PRODUCT D ON A2.FINPROD_ID = D.FINPROD_ID AND A2.FINPROD_TYPE = D.FINPROD_TYPE AND A2.BRANCH = D.BRANCH
WHERE A2.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX')

	AND D.MDATE >= STR_TO_DATE(#{vdate},'%Y-%m-%d')


	AND D.MDATE <=STR_TO_DATE(#{mdate},'%Y-%m-%d')

ORDER BY  A2.BOOKSET_ID,A2.FINPROD_TYPE,A2.FINPROD_ID,A2.BASE_SUBJECT_NATURE
